nxport_launcher_notify() {
  local message=$1 log=$2 tty
  [[ ${NXBOOTSTRAP_TEST_NO_TTY:-0} != 1 ]] || return 0
  for tty in /dev/tty0 /dev/console; do
    if [[ -c $tty && ! -L $tty ]]; then
      printf '%s; details: %s\n' "$message" "$log" > "$tty" 2>/dev/null &&
        return 0
    fi
  done
  return 0
}

nxport_launcher_on_exit() {
  local status=$1 message details directory existing log duplicate notified=0
  local -a destinations=()
  (( status != 0 )) || return 0
  [[ ${NXPORT_LAUNCHER_COMPLETED:-0} != 1 ]] || return 0

  message=${NXPORT_LAUNCHER_ERROR:-"${PORT_TITLE:-Port}: launcher failed before nxbootstrap opened its runtime log"}
