bootstrap_filename_expected=${NXPORT_BOOTSTRAP_LIBRARY:-unknown}
bootstrap_version_expected=${NXPORT_BOOTSTRAP_VERSION:-unknown}
bootstrap_sha256_expected=${NXPORT_BOOTSTRAP_SHA256:-unknown}
manifest_sha256_expected=${NXPORT_MANIFEST_SHA256:-unknown}
deployment_id_expected=${NXPORT_DEPLOYMENT_ID:-unknown}
paths tried:
${TRIED:-none}"
  printf '%s\n%s\n' "$message" "$details" >&2
  umask 077
  for directory in "${ORIGINAL_DIR:-}" "${SCRIPT_DIR:-}" "${TMPDIR:-/tmp}"; do
    [[ -n $directory && -d $directory ]] || continue
    duplicate=0
    for existing in "${destinations[@]}"; do
      if [[ $existing == "$directory" ]]; then
        duplicate=1
        break
      fi
    done
    (( duplicate == 0 )) || continue
    destinations+=("$directory")
    log=$directory/${PORT_ID:-port}-launcher-error.$$.log
    if (set -C; umask 077; printf '%s\n%s\n' "$message" "$details" > "$log") \
        2>/dev/null; then
      if (( notified == 0 )); then
        nxport_launcher_notify "$message" "$log"
        notified=1
      fi
    fi
  done
  return 0
}

trap 'nxport_launcher_on_exit $?' EXIT

nxport_deployment_receipt_matches() {
  local receipt=$1 line actual= expected first=1
  [[ -r $receipt ]] || return 1
  while IFS= read -r line || [[ -n $line ]]; do
    if (( first == 0 )); then
      actual+=$'\n'
    fi
    actual+=$line
    first=0
  done < "$receipt"
  (( first == 0 )) || return 1
  expected=${NXPORT_DEPLOYMENT_RECEIPT%$'\n'}
  [[ $actual == "$expected" ]]
}

nxport_file_sha256_matches() {
  local path=$1 expected=$2 actual
  command -v sha256sum >/dev/null 2>&1 || return 0
  actual=$(sha256sum "$path" 2>/dev/null) || return 1
  actual=${actual%%[[:space:]]*}
  [[ $actual == "$expected" ]]
}

