TRIED=
try_port() {
  local candidate=$1 bootstrap manifest receipt status
  shift
  TRIED="${TRIED}${TRIED:+
}$candidate"
  bootstrap=$candidate/$NXPORT_BOOTSTRAP_LIBRARY
  manifest=$candidate/nxport.json
  receipt=$candidate/nxdeployment.json
  [[ -d $candidate ]] || return 0
  NXPORT_LAUNCHER_CANDIDATE=$candidate
  NXPORT_BOOTSTRAP_PATH=$bootstrap
  export NXPORT_BOOTSTRAP_PATH
  NXPORT_LAUNCHER_STAGE=validate-deployment
  if [[ -f $bootstrap && ! -L $bootstrap ]]; then
    :
  else
    NXPORT_LAUNCHER_ERROR="$PORT_TITLE: versioned nxbootstrap is missing or unsafe"
    return 0
  fi
  if [[ ! -f $manifest || -L $manifest ]]; then
    NXPORT_LAUNCHER_ERROR="$PORT_TITLE: nxport manifest is missing or unsafe"
    return 0
  fi
  if [[ ! -f $receipt || -L $receipt ]]; then
    NXPORT_LAUNCHER_ERROR="$PORT_TITLE: deployment receipt is missing or unsafe"
    return 0
  fi
  if ! nxport_deployment_receipt_matches "$receipt" 2>/dev/null; then
    NXPORT_LAUNCHER_ERROR="$PORT_TITLE: deployment receipt is stale or invalid"
    return 0
  fi
  NXPORT_LAUNCHER_STAGE=verify-manifest
  if ! nxport_file_sha256_matches "$manifest" "$NXPORT_MANIFEST_SHA256"; then
    NXPORT_LAUNCHER_ERROR="$PORT_TITLE: nxport manifest checksum mismatch"
    return 0
  fi
  NXPORT_LAUNCHER_STAGE=verify-bootstrap
  if ! nxport_file_sha256_matches "$bootstrap" "$NXPORT_BOOTSTRAP_SHA256"; then
    NXPORT_LAUNCHER_ERROR="$PORT_TITLE: versioned nxbootstrap checksum mismatch"
    return 0
  fi
  NXPORT_GAME_DIR=$(CDPATH= cd -- "$candidate" 2>/dev/null && pwd -P) ||
    return 0
  [[ $NXPORT_GAME_DIR != / ]] || return 0
  NXPORT_BOOTSTRAP_PATH=$NXPORT_GAME_DIR/$NXPORT_BOOTSTRAP_LIBRARY
  export NXPORT_BOOTSTRAP_PATH
  NXPORT_LAUNCHER_STAGE=source-bootstrap
  NXPORT_LAUNCHER_ERROR="$PORT_TITLE: versioned nxbootstrap failed to load"
  source "$NXPORT_GAME_DIR/$NXPORT_BOOTSTRAP_LIBRARY" || exit 1
  NXPORT_LAUNCHER_STAGE=validate-bootstrap-version
  if [[ ${NXBOOTSTRAP_VERSION:-} != "$NXPORT_BOOTSTRAP_VERSION" ]]; then
    NXPORT_LAUNCHER_ERROR="$PORT_TITLE: nxbootstrap version mismatch; expected $NXPORT_BOOTSTRAP_VERSION"
    exit 1
  fi
  if ! declare -F nxbootstrap_main >/dev/null 2>&1; then
    NXPORT_LAUNCHER_ERROR="$PORT_TITLE: nxbootstrap_main is unavailable"
    exit 1
  fi
  NXPORT_LAUNCHER_STAGE=nxbootstrap-main
  NXPORT_LAUNCHER_ERROR=
  nxbootstrap_main "$@"
  status=$?
  NXPORT_LAUNCHER_COMPLETED=1
  trap - EXIT
  exit "$status"
}

# Relative discovery covers PortMaster copies/symlinks without choosing a CFW.
cursor=$SCRIPT_DIR
depth=0
while [[ $depth -lt 5 ]]; do
  try_port "$cursor/$PORT_ID" "$@"
  try_port "$cursor/ports/$PORT_ID" "$@"
  try_port "$cursor/Ports/$PORT_ID" "$@"
  parent=$(dirname -- "$cursor")
  [[ $parent != "$cursor" ]] || break
  cursor=$parent
  depth=$((depth + 1))
done

for rom_root in \
  /roms /roms2 /storage/roms /userdata/roms \
  /mnt/mmc /mnt/mmc/roms /mnt/mmc/ROMS \
  /mnt/sdcard /mnt/sdcard/roms /mnt/sdcard/ROMS
do
